"""
Simple Genetic Programming Symbolic Regression
================================================
A tiny, from-scratch implementation of symbolic regression using genetic
programming (GP) — the same "breeding/mutating formula trees" idea from
the notes.

Goal: given data (x, y), evolve a formula tree that predicts y from x,
without being told the formula shape in advance.

Run this directly in PyCharm (green play button / Shift+F10).
"""

import random
import math

# ----------------------------------------------------------------------
# 1. THE DATA — secretly generated by y = x^2 + 1
#    The algorithm does NOT know this formula. It only sees these pairs.
# ----------------------------------------------------------------------
X_DATA = [1, 2, 3, 4, 5, 6, 7]
Y_DATA = [x**2 + 1 for x in X_DATA]

print("Data the algorithm sees:")
for x, y in zip(X_DATA, Y_DATA):
    print(f"  x={x} -> y={y}")
print()

# ----------------------------------------------------------------------
# 2. EXPRESSION TREES
#    A node is either:
#      - a leaf: ('var',)        -> means "x"
#      - a leaf: ('const', 3.0)  -> means the number 3.0
#      - an operator: (op_symbol, left_subtree, right_subtree)
# ----------------------------------------------------------------------

BINARY_OPS = ['+', '-', '*']  # keep it simple: no division (avoids /0 headaches)


def random_leaf():
    """Make a random leaf: either the variable x, or a random constant."""
    if random.random() < 0.5:
        return ('var',)
    else:
        return ('const', float(random.randint(-5, 5)))


def random_tree(depth):
    """
    Build a random expression tree.
    depth = how many levels of operators are still allowed.
    depth 0 -> just return a leaf (stop growing).
    """
    if depth == 0 or random.random() < 0.3:
        return random_leaf()
    op = random.choice(BINARY_OPS)
    left = random_tree(depth - 1)
    right = random_tree(depth - 1)
    return (op, left, right)


def evaluate(tree, x):
    """Evaluate a tree for a given x value. Returns a number."""
    if tree[0] == 'var':
        return x
    if tree[0] == 'const':
        return tree[1]

    op, left, right = tree
    lval = evaluate(left, x)
    rval = evaluate(right, x)
    if op == '+':
        return lval + rval
    if op == '-':
        return lval - rval
    if op == '*':
        return lval * rval
    raise ValueError(f"Unknown operator {op}")


def tree_to_string(tree):
    """Turn a tree back into a readable formula string, e.g. '(x * x) + 1'."""
    if tree[0] == 'var':
        return 'x'
    if tree[0] == 'const':
        return str(round(tree[1], 3))
    op, left, right = tree
    return f"({tree_to_string(left)} {op} {tree_to_string(right)})"


def tree_size(tree):
    """Count nodes in the tree — used as the 'complexity' penalty."""
    if tree[0] in ('var', 'const'):
        return 1
    _, left, right = tree
    return 1 + tree_size(left) + tree_size(right)


# ----------------------------------------------------------------------
# 3. FITNESS
#    Lower score = better. We combine:
#      - error: how far off predictions are from real data
#      - a small complexity penalty, so it prefers simpler formulas
# ----------------------------------------------------------------------

COMPLEXITY_PENALTY = 0.01  # tune this to prefer simpler/more complex trees


def fitness(tree):
    total_error = 0.0
    for x, y_true in zip(X_DATA, Y_DATA):
        try:
            y_pred = evaluate(tree, x)
        except (OverflowError, ZeroDivisionError):
            return float('inf')  # broken formula -> worst possible score
        total_error += (y_pred - y_true) ** 2  # squared error

    if math.isnan(total_error) or math.isinf(total_error):
        return float('inf')

    return total_error + COMPLEXITY_PENALTY * tree_size(tree)


# ----------------------------------------------------------------------
# 4. MUTATION & CROSSOVER — the "twist" and "mix" from the notes
# ----------------------------------------------------------------------

def get_all_subtrees(tree, path=()):
    """List every subtree in `tree`, tagged with its location (path)."""
    subtrees = [(path, tree)]
    if tree[0] not in ('var', 'const'):
        _, left, right = tree
        subtrees += get_all_subtrees(left, path + (1,))
        subtrees += get_all_subtrees(right, path + (2,))
    return subtrees


def replace_at_path(tree, path, new_subtree):
    """Return a copy of `tree` with the node at `path` replaced."""
    if not path:
        return new_subtree
    op, left, right = tree
    if path[0] == 1:
        return (op, replace_at_path(left, path[1:], new_subtree), right)
    else:
        return (op, left, replace_at_path(right, path[1:], new_subtree))


def mutate(tree):
    """Pick a random spot in the tree and replace it with a fresh random subtree."""
    subtrees = get_all_subtrees(tree)
    path, _ = random.choice(subtrees)
    new_piece = random_tree(depth=2)
    return replace_at_path(tree, path, new_piece)


def crossover(tree_a, tree_b):
    """Swap a random subtree from tree_b into a random spot in tree_a."""
    subtrees_a = get_all_subtrees(tree_a)
    subtrees_b = get_all_subtrees(tree_b)
    path_a, _ = random.choice(subtrees_a)
    _, piece_from_b = random.choice(subtrees_b)
    return replace_at_path(tree_a, path_a, piece_from_b)


# ----------------------------------------------------------------------
# 5. THE MAIN EVOLUTION LOOP — this is the "rounds" from the notes:
#    Select Fittest -> Mutate/Crossover -> (Replace) -> repeat
# ----------------------------------------------------------------------

POPULATION_SIZE = 300
NUM_GENERATIONS = 150
INITIAL_DEPTH = 3
TOURNAMENT_SIZE = 5  # how many random contestants compete when picking a parent


def tournament_select(population, scored):
    """Pick TOURNAMENT_SIZE random individuals, return the best of them."""
    contestants = random.sample(list(zip(population, scored)), TOURNAMENT_SIZE)
    contestants.sort(key=lambda pair: pair[1])  # lowest fitness score wins
    return contestants[0][0]


def run_evolution():
    # Round 0: random junky guesses (the initial "bucket")
    population = [random_tree(INITIAL_DEPTH) for _ in range(POPULATION_SIZE)]

    best_tree = None
    best_score = float('inf')

    for generation in range(NUM_GENERATIONS):
        scored = [fitness(t) for t in population]

        # Track the best formula seen so far
        gen_best_idx = scored.index(min(scored))
        if scored[gen_best_idx] < best_score:
            best_score = scored[gen_best_idx]
            best_tree = population[gen_best_idx]

        # Print progress every 10 rounds so you can watch it improve
        if generation % 10 == 0 or generation == NUM_GENERATIONS - 1:
            print(f"Generation {generation:3d} | best score so far: "
                  f"{best_score:.4f} | formula: {tree_to_string(best_tree)}")

        # Build the next generation
        new_population = [best_tree]  # keep the best one, always (elitism)
        while len(new_population) < POPULATION_SIZE:
            parent_a = tournament_select(population, scored)
            if random.random() < 0.5:
                parent_b = tournament_select(population, scored)
                child = crossover(parent_a, parent_b)
            else:
                child = mutate(parent_a)
            new_population.append(child)

        population = new_population

    return best_tree, best_score


if __name__ == "__main__":
    best_formula, score = run_evolution()
    print()
    print("=" * 50)
    print(f"Best formula found: y = {tree_to_string(best_formula)}")
    print(f"Final fitness score: {score:.4f}  (lower = better)")
    print("=" * 50)
    print()
    print("Check it against the data:")
    for x, y_true in zip(X_DATA, Y_DATA):
        y_pred = evaluate(best_formula, x)
        print(f"  x={x} -> predicted={y_pred:.2f}, real={y_true}")
